11	struct HomeScreenRoomList: View {
12	    @ObservedObject var context: HomeScreenViewModel.Context
13	    
14	    var body: some View {
15	        // Hide the room list when the search bar is focused but the query is empty
16	        // This works hand in hand with the room list service layer filtering and
17	        // avoids glitches when focusing the search bar
18	        if !context.viewState.shouldHideRoomList {
19	            content
20	        }
21	    }
22	    
23	    private var content: some View {
24	        ForEach(context.viewState.visibleRooms) { room in
25	            switch room.type {
26	            case .placeholder:
27	                HomeScreenRoomCell(room: room, isSelected: false, mediaProvider: context.mediaProvider, action: context.send)
28	                    .redacted(reason: .placeholder)
29	            case .invite:
30	                HomeScreenInviteCell(room: room, context: context, hideInviteAvatars: context.viewState.hideInviteAvatars)
31	            case .knock:
32	                HomeScreenKnockedCell(room: room, context: context)
33	            case .room:
34	                let isSelected = context.viewState.selectedRoomID == room.id
35	                
36	                HomeScreenRoomCell(room: room, isSelected: isSelected, mediaProvider: context.mediaProvider, action: context.send)
37	                    .contextMenu {
38	                        if room.badges.isDotShown {
39	                            Button {
40	                                context.send(viewAction: .markRoomAsRead(roomIdentifier: room.id))
41	                            } label: {
42	                                Label(L10n.screenRoomlistMarkAsRead, icon: \.markAsRead)
43	                            }
44	                        } else {
45	                            Button {
46	                                context.send(viewAction: .markRoomAsUnread(roomIdentifier: room.id))
47	                            } label: {
48	                                Label(L10n.screenRoomlistMarkAsUnread, icon: \.markAsUnread)
49	                            }
50	                        }
51	                        
52	                        if room.isFavourite {
53	                            Button {
54	                                context.send(viewAction: .markRoomAsFavourite(roomIdentifier: room.id, isFavourite: false))
55	                            } label: {
56	                                Label(L10n.commonFavourited, icon: \.favouriteSolid)
57	                            }
58	                        } else {
59	                            Button {
60	                                context.send(viewAction: .markRoomAsFavourite(roomIdentifier: room.id, isFavourite: true))
61	                            } label: {
62	                                Label(L10n.commonFavourite, icon: \.favourite)
63	                            }
64	                        }
65	                        
66	                        Button {
67	                            context.send(viewAction: .showRoomDetails(roomIdentifier: room.id))
68	                        } label: {
69	                            Label(L10n.commonSettings, icon: \.settings)
70	                        }
71	                        
72	                        if context.viewState.reportRoomEnabled {
73	                            Button(role: .destructive) {
74	                                context.send(viewAction: .reportRoom(roomIdentifier: room.id))
75	                            } label: {
76	                                Label(L10n.actionReportRoom, icon: \.chatProblem)
77	                            }
78	                        }
79	                        
80	                        Button(role: .destructive) {
81	                            context.send(viewAction: .leaveRoom(roomIdentifier: room.id))
82	                        } label: {
83	                            Label(L10n.actionLeaveRoom, icon: \.leave)
84	                        }
85	                    }
86	            }
87	        }
88	    }
89	}
